cat > /workspace/submission/main.py <<'PY'
"""Offline DNS model-based regression workbench.

Reads one JSON document from stdin, builds the frozen local resolver model,
adjudicates observations, and selects a minimum-cost diagnostic query basis.
All supporting code lives in this single file.
"""

import ipaddress
import json
import math
import re
import sys

MAX_INPUT_BYTES = 8 * 1024 * 1024
MAX_DEPTH = 32

ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}", re.ASCII)
LABEL_RE = re.compile(r"[A-Za-z0-9_-]+", re.ASCII)
A_OCTET_RE = re.compile(r"0|[1-9][0-9]{0,2}", re.ASCII)

TYPES = frozenset(("A", "AAAA", "TXT", "CNAME"))
RCODES = frozenset(("NOERROR", "NXDOMAIN", "SERVFAIL", "REFUSED"))


class Invalid(Exception):
    pass


# ---------------------------------------------------------------------------
# Input decoding and generic checks


def _reject_constant(_text):
    raise Invalid("nonfinite")


def _pairs(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise Invalid("duplicate key")
        obj[key] = value
    return obj


def _read_document():
    raw = sys.stdin.buffer.read(MAX_INPUT_BYTES + 1)
    if len(raw) > MAX_INPUT_BYTES:
        # Consume the remainder in bounded chunks so a writer does not see a
        # broken pipe; the document is invalid regardless.
        while True:
            chunk = sys.stdin.buffer.read(1 << 20)
            if not chunk:
                break
        raise Invalid("too large")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise Invalid("bad utf-8")
    try:
        doc = json.loads(text, object_pairs_hook=_pairs, parse_constant=_reject_constant)
    except Invalid:
        raise
    except Exception:
        raise Invalid("bad json")
    return doc


def _check_depth_and_numbers(root):
    if not isinstance(root, (dict, list)):
        if isinstance(root, float) and not math.isfinite(root):
            raise Invalid("nonfinite")
        return
    stack = [(root, 1)]
    while stack:
        obj, depth = stack.pop()
        if depth > MAX_DEPTH:
            raise Invalid("depth")
        if isinstance(obj, dict):
            values = obj.values()
        else:
            values = obj
        for value in values:
            if isinstance(value, (dict, list)):
                stack.append((value, depth + 1))
            elif isinstance(value, float):
                if not math.isfinite(value):
                    raise Invalid("nonfinite")


def _require_object(obj, keys):
    if type(obj) is not dict:
        raise Invalid("not object")
    if len(obj) != len(keys) or set(obj.keys()) != keys:
        raise Invalid("keys")
    return obj


def _require_list(obj):
    if type(obj) is not list:
        raise Invalid("not array")
    return obj


# ---------------------------------------------------------------------------
# Names, records, zones


def canon_name(value):
    if type(value) is not str:
        raise Invalid("name type")
    if not value.isascii():
        raise Invalid("name ascii")
    if value == ".":
        return "."
    if not value.endswith("."):
        raise Invalid("relative name")
    body = value[:-1]
    if body == "":
        raise Invalid("empty name")
    labels = body.split(".")
    wire = 1
    for label in labels:
        if label == "*":
            length = 1
        else:
            if len(label) < 1 or len(label) > 63 or LABEL_RE.fullmatch(label) is None:
                raise Invalid("label")
            length = len(label)
        wire += length + 1
    if wire > 255:
        raise Invalid("wire length")
    return value.lower()


def label_count(name):
    return 0 if name == "." else name.count(".")


def parent_name(name):
    if name == ".":
        return None
    idx = name.find(".")
    rest = name[idx + 1:]
    return "." if rest == "" else rest


def at_or_below(name, origin):
    if origin == ".":
        return True
    return name == origin or name.endswith("." + origin)


def norm_data(rtype, data):
    if type(data) is not str:
        raise Invalid("data type")
    if rtype == "A":
        parts = data.split(".")
        if len(parts) != 4:
            raise Invalid("A")
        for part in parts:
            if A_OCTET_RE.fullmatch(part) is None:
                raise Invalid("A")
            if int(part) > 255:
                raise Invalid("A")
        return data
    if rtype == "AAAA":
        if "%" in data:
            raise Invalid("AAAA scope")
        try:
            return ipaddress.IPv6Address(data).compressed
        except Exception:
            raise Invalid("AAAA")
    if rtype == "TXT":
        if len(data) > 256:
            raise Invalid("TXT length")
        for ch in data:
            code = ord(ch)
            if code < 0x20 or code > 0x7E:
                raise Invalid("TXT char")
        return data
    if rtype == "CNAME":
        return canon_name(data)
    raise Invalid("type")


def validate_record(obj):
    _require_object(obj, {"owner", "type", "data"})
    owner = canon_name(obj["owner"])
    rtype = obj["type"]
    if type(rtype) is not str or rtype not in TYPES:
        raise Invalid("record type")
    data = norm_data(rtype, obj["data"])
    return owner, rtype, data


def validate_zone(raw):
    _require_object(raw, {"origin", "records"})
    origin = canon_name(raw["origin"])
    records_raw = _require_list(raw["records"])
    entries = []
    for item in records_raw:
        entries.append(validate_record(item))
    grouped = {}
    for owner, rtype, data in entries:
        if not at_or_below(owner, origin):
            raise Invalid("owner outside zone")
        by_type = grouped.setdefault(owner, {})
        data_set = by_type.setdefault(rtype, set())
        data_set.add(data)
        if len(data_set) > 64:
            raise Invalid("rrset")
    for owner, by_type in grouped.items():
        if "CNAME" in by_type:
            if owner == origin:
                raise Invalid("cname at origin")
            if len(by_type["CNAME"]) != 1:
                raise Invalid("cname targets")
            if len(by_type) != 1:
                raise Invalid("cname coexist")
    existing = set()
    for owner in grouped:
        node = owner
        while True:
            existing.add(node)
            if node == origin:
                break
            node = parent_name(node)
            if node is None:
                raise Invalid("ancestor")
    return {
        "origin": origin,
        "records": grouped,
        "existing": existing,
        "labels": label_count(origin),
        "entries": len(entries),
    }


# ---------------------------------------------------------------------------
# Profiles, queries, observations


def validate_profile(raw):
    _require_object(raw, {"id", "max_aliases", "cname", "wildcard"})
    pid = raw["id"]
    if type(pid) is not str or ID_RE.fullmatch(pid) is None:
        raise Invalid("profile id")
    max_aliases = raw["max_aliases"]
    if type(max_aliases) is not int or max_aliases < 0 or max_aliases > 64:
        raise Invalid("max_aliases")
    cname = raw["cname"]
    if type(cname) is not str or cname not in ("follow", "stop"):
        raise Invalid("cname mode")
    wildcard = raw["wildcard"]
    if type(wildcard) is not str or wildcard not in ("rfc", "off", "one-label"):
        raise Invalid("wildcard mode")
    return {
        "id": pid,
        "max_aliases": max_aliases,
        "cname": cname,
        "wildcard": wildcard,
    }


def validate_query(raw):
    _require_object(raw, {"id", "name", "type", "cost"})
    qid = raw["id"]
    if type(qid) is not str or ID_RE.fullmatch(qid) is None:
        raise Invalid("query id")
    name = canon_name(raw["name"])
    qtype = raw["type"]
    if type(qtype) is not str or qtype not in TYPES:
        raise Invalid("query type")
    cost = raw["cost"]
    if type(cost) is not int or cost < 1 or cost > 1000:
        raise Invalid("query cost")
    return {"id": qid, "name": name, "type": qtype, "cost": cost}


def validate_observation(raw, query_ids, profile_ids):
    _require_object(raw, {"id", "query", "profile", "result"})
    oid = raw["id"]
    if type(oid) is not str or ID_RE.fullmatch(oid) is None:
        raise Invalid("observation id")
    qref = raw["query"]
    if type(qref) is not str or qref not in query_ids:
        raise Invalid("observation query")
    pref = raw["profile"]
    if type(pref) is not str or pref not in profile_ids:
        raise Invalid("observation profile")
    result = raw["result"]
    if type(result) is not dict:
        raise Invalid("result")
    status = result.get("status")
    if type(status) is not str:
        raise Invalid("status")
    if status == "timeout":
        _require_object(result, {"status"})
        return {"id": oid, "query": qref, "profile": pref, "timeout": True,
                "rcode": None, "answer": None}
    if status == "response":
        _require_object(result, {"status", "rcode", "answer"})
        rcode = result["rcode"]
        if type(rcode) is not str or rcode not in RCODES:
            raise Invalid("rcode")
        answer_raw = _require_list(result["answer"])
        if len(answer_raw) > 128:
            raise Invalid("observed answer size")
        answer = []
        for item in answer_raw:
            answer.append(validate_record(item))
        return {"id": oid, "query": qref, "profile": pref, "timeout": False,
                "rcode": rcode, "answer": answer}
    raise Invalid("status value")


# ---------------------------------------------------------------------------
# Resolver model


def select_zone(zones, name):
    best = None
    best_labels = -1
    for zone in zones:
        if at_or_below(name, zone["origin"]) and zone["labels"] > best_labels:
            best = zone
            best_labels = zone["labels"]
    return best


def resolve(query, profile, zones):
    current = query["name"]
    qtype = query["type"]
    seen = set()
    aliases = 0
    answer = []
    trace = []

    while True:
        trace.append(current)
        if current in seen:
            rcode = "SERVFAIL"
            termination = "LOOP"
            break
        seen.add(current)

        zone = select_zone(zones, current)
        if zone is None:
            if aliases == 0:
                rcode = "REFUSED"
                termination = "OUTSIDE"
            else:
                rcode = "NOERROR"
                termination = "EXTERNAL"
            break

        if current in zone["existing"]:
            source = current
        else:
            source = None
            mode = profile["wildcard"]
            if mode != "off":
                encloser = parent_name(current)
                while encloser is not None and encloser not in zone["existing"]:
                    encloser = parent_name(encloser)
                if encloser is not None:
                    wildcard_name = "*." if encloser == "." else "*." + encloser
                    if wildcard_name in zone["existing"]:
                        if mode == "one-label":
                            if label_count(current) != label_count(encloser) + 1:
                                wildcard_name = None
                        source = wildcard_name
            if source is None:
                rcode = "NXDOMAIN"
                termination = "NXDOMAIN"
                break

        rrset = zone["records"].get(source)
        if rrset is None:
            cname_data = ()
            type_data = ()
        else:
            cname_data = rrset.get("CNAME", ())
            type_data = rrset.get(qtype, ())

        if qtype == "CNAME":
            if cname_data:
                for data in sorted(cname_data):
                    answer.append({"owner": current, "type": "CNAME", "data": data})
                termination = "ANSWER"
            else:
                termination = "NODATA"
            rcode = "NOERROR"
            break

        if cname_data:
            if profile["cname"] == "stop":
                for data in sorted(cname_data):
                    answer.append({"owner": current, "type": "CNAME", "data": data})
                rcode = "NOERROR"
                termination = "CNAME_STOP"
                break
            if aliases == profile["max_aliases"]:
                rcode = "SERVFAIL"
                termination = "LIMIT"
                break
            target = sorted(cname_data)[0]
            for data in sorted(cname_data):
                answer.append({"owner": current, "type": "CNAME", "data": data})
            aliases += 1
            current = target
            continue

        if type_data:
            for data in sorted(type_data):
                answer.append({"owner": current, "type": qtype, "data": data})
            termination = "ANSWER"
        else:
            termination = "NODATA"
        rcode = "NOERROR"
        break

    return {
        "query": query["id"],
        "profile": profile["id"],
        "rcode": rcode,
        "termination": termination,
        "final_name": current,
        "answer": answer,
        "trace": trace,
    }


def projection(run):
    return (
        run["rcode"],
        frozenset((rec["owner"], rec["type"], rec["data"]) for rec in run["answer"]),
    )


# ---------------------------------------------------------------------------
# Diagnostic basis


def minimum_basis(queries, profiles, signatures, classes):
    """Return (basis_ids, cost, count).

    Enumerates every subset of candidate queries (at most 20) after removing
    zero-coverage queries and queries with duplicate coverage.  Minimises
    (total cost, selected count) lexicographically.
    """
    class_of = {}
    for index, members in enumerate(classes):
        for pid in members:
            class_of[pid] = index

    pair_keys = []
    for i, p1 in enumerate(profiles):
        for p2 in profiles[i + 1:]:
            if class_of[p1] != class_of[p2]:
                pair_keys.append((p1, p2))

    full = (1 << len(pair_keys)) - 1
    if full == 0:
        return [], 0, 0

    masks = {}
    costs = {}
    for query in queries:
        qid = query["id"]
        mask = 0
        for bit, (p1, p2) in enumerate(pair_keys):
            if signatures[(qid, p1)] != signatures[(qid, p2)]:
                mask |= 1 << bit
        if mask == 0:
            continue
        if mask in masks:
            if query["cost"] < costs[mask]:
                masks[mask] = qid
                costs[mask] = query["cost"]
        else:
            masks[mask] = qid
            costs[mask] = query["cost"]

    items = sorted(masks.items(), key=lambda kv: kv[1])
    m = len(items)
    subset_masks = [kv[0] for kv in items]
    subset_costs = [costs[kv[0]] for kv in items]
    subset_ids = [kv[1] for kv in items]

    size = 1 << m
    coverage = [0] * size
    total_cost = [0] * size
    total_count = [0] * size

    best_key = None
    best_mask = 0
    for mask in range(size):
        if mask:
            low = mask & -mask
            index = low.bit_length() - 1
            prev = mask ^ low
            coverage[mask] = coverage[prev] | subset_masks[index]
            total_cost[mask] = total_cost[prev] + subset_costs[index]
            total_count[mask] = total_count[prev] + 1
        if coverage[mask] == full:
            key = (total_cost[mask], total_count[mask])
            if best_key is None or key < best_key:
                best_key = key
                best_mask = mask

    selected = []
    bits = best_mask
    while bits:
        low = bits & -bits
        index = low.bit_length() - 1
        selected.append(subset_ids[index])
        bits ^= low
    selected.sort()
    return selected, best_key[0], best_key[1]


# ---------------------------------------------------------------------------
# Analysis


def analyze(document):
    _require_object(document, {"zones", "profiles", "queries", "observations"})

    zones_raw = _require_list(document["zones"])
    profiles_raw = _require_list(document["profiles"])
    queries_raw = _require_list(document["queries"])
    observations_raw = _require_list(document["observations"])

    if len(zones_raw) > 16:
        raise Invalid("zones count")
    if len(profiles_raw) < 1 or len(profiles_raw) > 8:
        raise Invalid("profiles count")
    if len(queries_raw) > 20:
        raise Invalid("queries count")
    if len(observations_raw) > 64:
        raise Invalid("observations count")

    zones = []
    origins = set()
    total_record_entries = 0
    for raw in zones_raw:
        zone = validate_zone(raw)
        if zone["origin"] in origins:
            raise Invalid("duplicate origin")
        origins.add(zone["origin"])
        total_record_entries += zone["entries"]
        if total_record_entries > 1024:
            raise Invalid("record entries")
        zones.append(zone)

    profiles = []
    profile_ids = set()
    for raw in profiles_raw:
        profile = validate_profile(raw)
        if profile["id"] in profile_ids:
            raise Invalid("duplicate profile")
        profile_ids.add(profile["id"])
        profiles.append(profile)
    profiles.sort(key=lambda p: p["id"])

    queries = []
    query_ids = set()
    for raw in queries_raw:
        query = validate_query(raw)
        if query["id"] in query_ids:
            raise Invalid("duplicate query")
        query_ids.add(query["id"])
        queries.append(query)
    queries.sort(key=lambda q: q["id"])

    observations = []
    observation_ids = set()
    for raw in observations_raw:
        observation = validate_observation(raw, query_ids, profile_ids)
        if observation["id"] in observation_ids:
            raise Invalid("duplicate observation")
        observation_ids.add(observation["id"])
        observations.append(observation)
    observations.sort(key=lambda o: o["id"])

    runs = []
    signatures = {}
    for query in queries:
        for profile in profiles:
            run = resolve(query, profile, zones)
            runs.append(run)
            signatures[(query["id"], profile["id"])] = projection(run)

    audits = []
    for observation in observations:
        if observation["timeout"]:
            audits.append({"id": observation["id"], "verdict": "unobserved", "different": []})
            continue
        run_rcode, run_answer = signatures[(observation["query"], observation["profile"])]
        observed_rcode = observation["rcode"]
        observed_answer = frozenset(observation["answer"])
        different = []
        if observed_rcode != run_rcode:
            different.append("rcode")
        if observed_answer != run_answer:
            different.append("answer")
        if different:
            audits.append({"id": observation["id"], "verdict": "divergence", "different": different})
        else:
            audits.append({"id": observation["id"], "verdict": "match", "different": []})

    # Equivalence classes, over the full candidate query set.
    profile_ids_sorted = [p["id"] for p in profiles]
    assigned = set()
    classes = []
    for pid in profile_ids_sorted:
        if pid in assigned:
            continue
        members = []
        for other in profile_ids_sorted:
            if other in assigned:
                continue
            equivalent = True
            for query in queries:
                if signatures[(query["id"], pid)] != signatures[(query["id"], other)]:
                    equivalent = False
                    break
            if equivalent:
                members.append(other)
        members.sort()
        for member in members:
            assigned.add(member)
        classes.append(members)
    classes.sort()

    basis, cost, count = minimum_basis(queries, profile_ids_sorted, signatures, classes)

    return {
        "runs": runs,
        "audits": audits,
        "diagnostic": {
            "equivalence": classes,
            "basis": basis,
            "cost": cost,
            "count": count,
        },
    }


def _emit(obj):
    sys.stdout.write(json.dumps(obj, separators=(",", ":"), ensure_ascii=True))
    sys.stdout.write("\n")


def main():
    try:
        document = _read_document()
        _check_depth_and_numbers(document)
        result = analyze(document)
    except Invalid:
        _emit({"error": "invalid-input"})
        return
    except Exception:
        _emit({"error": "invalid-input"})
        return
    _emit(result)


if __name__ == "__main__":
    main()
