cat > /workspace/tmp/fuzz.py <<'PY'
import json, random, subprocess, itertools, sys
MAIN=['python3','-I','/workspace/submission/main.py']

def lower(n): return n.lower()
def labels(n): return [] if n=='.' else n[:-1].split('.')
def lc(n): return 0 if n=='.' else n.count('.')
def parent(n):
    if n=='.': return None
    i=n.find('.'); r=n[i+1:]
    return '.' if r=='' else r
def below(name,origin):
    if origin=='.': return True
    return name==origin or name.endswith('.'+origin)

# independent resolver: recursive-ish with dict structures
def build_zones(zdocs):
    out=[]
    for z in zdocs:
        origin=lower(z['origin'])
        rr={}
        existing={origin}
        for r in z['records']:
            o=lower(r['owner']); t=r['type']; d=r['data']
            if t=='CNAME': d=lower(d)
            if t=='AAAA':
                import ipaddress; d=ipaddress.IPv6Address(d).compressed
            rr.setdefault(o,{}).setdefault(t,set()).add(d)
            n=o
            while n!=origin:
                n=parent(n); existing.add(n)
        out.append({'origin':origin,'rr':rr,'existing':existing,'lc':lc(origin)})
    return out

def zone_for(zones,name):
    cand=[z for z in zones if below(name,z['origin'])]
    if not cand: return None
    return max(cand,key=lambda z:z['lc'])

def src_for(z,name,prof):
    if name in z['existing']: return name
    mode=prof['wildcard']
    if mode=='off': return None
    e=parent(name)
    while e not in z['existing']:
        e=parent(e)
        if e is None: return None
    w='*.' if e=='.' else '*.'+e
    if w not in z['existing']: return None
    if mode=='one-label' and lc(name)!=lc(e)+1: return None
    return w

def resolve(q,prof,zones):
    cur=q['name']; seen=set(); ans=[]; tr=[]; al=0
    while True:
        tr.append(cur)
        if cur in seen:
            return ('SERVFAIL','LOOP',cur,ans,tr)
        seen.add(cur)
        z=zone_for(zones,cur)
        if z is None:
            if al==0: return ('REFUSED','OUTSIDE',cur,ans,tr)
            return ('NOERROR','EXTERNAL',cur,ans,tr)
        s=src_for(z,cur,prof)
        if s is None:
            return ('NXDOMAIN','NXDOMAIN',cur,ans,tr)
        c=z['rr'].get(s,{}).get('CNAME',set())
        t=z['rr'].get(s,{}).get(q['type'],set())
        if q['type']=='CNAME':
            for d in sorted(c): ans.append((cur,'CNAME',d))
            return ('NOERROR','ANSWER' if c else 'NODATA',cur,ans,tr)
        if c:
            if prof['cname']=='stop':
                for d in sorted(c): ans.append((cur,'CNAME',d))
                return ('NOERROR','CNAME_STOP',cur,ans,tr)
            if al==prof['max_aliases']:
                return ('SERVFAIL','LIMIT',cur,ans,tr)
            for d in sorted(c): ans.append((cur,'CNAME',d))
            al+=1; cur=sorted(c)[0]; continue
        if t:
            for d in sorted(t): ans.append((cur,q['type'],d))
            return ('NOERROR','ANSWER',cur,ans,tr)
        return ('NOERROR','NODATA',cur,ans,tr)

def check(doc, actual):
    zs=build_zones(doc['zones'])
    prods=sorted(doc['profiles'],key=lambda p:p['id'])
    qs=sorted(doc['queries'],key=lambda q:q['id'])
    expected_runs=[]
    matrix={}
    for q in qs:
        for p in prods:
            rc,term,fn,ans,tr=resolve(q,p,zs)
            ad=[{'owner':o,'type':t,'data':d} for o,t,d in ans]
            expected_runs.append({'query':q['id'],'profile':p['id'],'rcode':rc,'termination':term,'final_name':fn,'answer':ad,'trace':tr})
            matrix[(q['id'],p['id'])]=(rc,frozenset(ans))
    assert actual['runs']==expected_runs, ("runs", actual['runs'], expected_runs)
    # audits
    expa=[]
    for o in sorted(doc['observations'],key=lambda x:x['id']):
        r=o['result']
        if r['status']=='timeout':
            expa.append({'id':o['id'],'verdict':'unobserved','different':[]}); continue
        rr,ra=matrix[(o['query'],o['profile'])]
        oa=frozenset((lower(x['owner']),x['type'], x['data'] if x['type']!='CNAME' else lower(x['data'])) for x in r['answer'])
        # assume data canonical for A, TXT; AAAA in fuzz canonical
        diff=[]
        if r['rcode']!=rr: diff.append('rcode')
        if oa!=ra: diff.append('answer')
        expa.append({'id':o['id'],'verdict':'divergence' if diff else 'match','different':diff})
    assert actual['audits']==expa, ("audits",actual['audits'],expa)
    # equivalence
    pids=[p['id'] for p in prods]
    qids=[q['id'] for q in qs]
    classes=[]; assigned=set()
    for p in pids:
        if p in assigned: continue
        mem=[x for x in pids if x not in assigned and all(matrix[(q,p)]==matrix[(q,x)] for q in qids)]
        for x in mem: assigned.add(x)
        classes.append(sorted(mem))
    classes.sort()
    assert actual['diagnostic']['equivalence']==classes,(actual['diagnostic']['equivalence'],classes)
    # exact basis brute force over all subsets
    pairs=[(a,b) for a,b in itertools.combinations(pids,2) if any(matrix[(q,a)]!=matrix[(q,b)] for q in qids)]
    best=None; bestbasis=None
    costs={q['id']:q['cost'] for q in qs}
    for r in range(len(qids)+1):
        for sub in itertools.combinations(qids,r):
            if all(any(matrix[(q,a)]!=matrix[(q,b)] for q in sub) for a,b in pairs):
                key=(sum(costs[q] for q in sub),len(sub))
                if best is None or key<best:
                    best=key; bestbasis=sub
    d=actual['diagnostic']
    assert (d['cost'],d['count'])==best,(d,best)
    assert d['basis']==sorted(d['basis'])
    assert sum(costs[q] for q in d['basis'])==d['cost'] and len(d['basis'])==d['count']
    assert all(any(matrix[(q,a)]!=matrix[(q,b)] for q in d['basis']) for a,b in pairs)

def gen_name(label):
    # a simple unique canonical name below a chosen base
    return label+'.'

def make_doc(rng):
    origins=rng.sample(['.','test.','sub.test.','a.test.','x.'], rng.randint(0,3))
    zones=[]
    for origin in origins:
        recs=[]
        # possible owners below origin
        def owners():
            base=[] if origin=='.' else labels(origin)
            for k in range(1,4):
                for _ in range(3):
                    labs=[rng.choice(['a','b','c','*','x','y']) for _ in range(k)]
                    recs_owner='.'.join(labs+base)+'.'
                    yield recs_owner
        ownerset=list(set(owners()))
        for o in rng.sample(ownerset,rng.randint(0,min(6,len(ownerset)))):
            # choose type; CNAME owners must sole type and one target
            if rng.random()<0.25:
                tgt=rng.choice(['a.test.','b.test.','out.','self.test.','*.test.',o])
                recs.append({'owner':o,'type':'CNAME','data':tgt})
            else:
                ts=rng.sample(['A','AAAA','TXT'],rng.randint(1,2))
                for t in ts:
                    for _ in range(rng.randint(1,2)):
                        if t=='A': d='192.0.2.%d'%rng.randint(0,255)
                        elif t=='AAAA': d=rng.choice(['2001:db8::1','::1','2001:DB8:0:0:0:0:0:2'])
                        else: d=rng.choice(['x','MiXeD',''])
                        recs.append({'owner':o,'type':t,'data':d})
        # NOTE possible cname coexist -> invalid; skip zones with conflict by validation later
        zones.append({'origin':origin,'records':recs})
    profiles=[]
    for i in range(rng.randint(1,4)):
        profiles.append({'id':'p%d'%i,'max_aliases':rng.randint(0,3),'cname':rng.choice(['follow','stop']),'wildcard':rng.choice(['rfc','off','one-label'])})
    queries=[]
    names=['a.test.','b.test.','x.a.test.','*.test.','self.test.','outside.','p.q.test.','sub.test.','.']
    for i in range(rng.randint(0,7)):
        queries.append({'id':'q%d'%i,'name':rng.choice(names),'type':rng.choice(['A','AAAA','TXT','CNAME']),'cost':rng.randint(1,5)})
    observations=[]
    return {'zones':zones,'profiles':profiles,'queries':queries,'observations':observations}

def main():
    rng=random.Random(12345)
    tested=0; invalids=0
    for it in range(500):
        doc=make_doc(rng)
        raw=json.dumps(doc).encode()
        p=subprocess.run(MAIN,input=raw,capture_output=True)
        assert p.returncode==0
        actual=json.loads(p.stdout)
        if 'error' in actual:
            invalids+=1; continue
        try:
            check(doc,actual)
        except AssertionError as e:
            print("FAIL iteration",it)
            print(json.dumps(doc,indent=1))
            print("ACTUAL",json.dumps(actual,indent=1))
            print(e)
            return
        tested+=1
    print("ok tested",tested,"invalids",invalids)
main()
