"""Offline DNS model-based regression workbench.

Reads one JSON document from stdin, builds the frozen local resolver model,
adjudicates observations, and selects a minimum-cost diagnostic query basis.
All supporting code lives in this single file.
"""

import ipaddress
import json
import math
import re
import sys
from array import array

MAX_INPUT_BYTES = 8 * 1024 * 1024
MAX_DEPTH = 32

ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}", re.ASCII)
LABEL_RE = re.compile(r"[A-Za-z0-9_-]+", re.ASCII)
A_OCTET_RE = re.compile(r"0|[1-9][0-9]{0,2}", re.ASCII)

TYPES = frozenset(("A", "AAAA", "TXT", "CNAME"))
RCODES = frozenset(("NOERROR", "NXDOMAIN", "SERVFAIL", "REFUSED"))


class Invalid(Exception):
    pass


# ---------------------------------------------------------------------------
# Input decoding and generic checks


def _reject_constant(_text):
    raise Invalid("nonfinite")


def _pairs(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise Invalid("duplicate key")
        obj[key] = value
    return obj


def _read_document():
    raw = sys.stdin.buffer.read(MAX_INPUT_BYTES + 1)
    if len(raw) > MAX_INPUT_BYTES:
        # Consume the remainder in bounded chunks so a writer does not see a
        # broken pipe; the document is invalid regardless.
        while True:
            chunk = sys.stdin.buffer.read(1 << 20)
            if not chunk:
                break
        raise Invalid("too large")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise Invalid("bad utf-8")
