            type_data = rrset.get(qtype, ())

        if qtype == "CNAME":
            if cname_data:
                for data in sorted(cname_data):
                    answer.append({"owner": current, "type": "CNAME", "data": data})
                termination = "ANSWER"
            else:
                termination = "NODATA"
            rcode = "NOERROR"
            break

        if cname_data:
            if profile["cname"] == "stop":
                for data in sorted(cname_data):
                    answer.append({"owner": current, "type": "CNAME", "data": data})
                rcode = "NOERROR"
                termination = "CNAME_STOP"
                break
            if aliases == profile["max_aliases"]:
                rcode = "SERVFAIL"
                termination = "LIMIT"
                break
            target = sorted(cname_data)[0]
            for data in sorted(cname_data):
                answer.append({"owner": current, "type": "CNAME", "data": data})
            aliases += 1
            current = target
            continue

        if type_data:
            for data in sorted(type_data):
                answer.append({"owner": current, "type": qtype, "data": data})
            termination = "ANSWER"
        else:
            termination = "NODATA"
        rcode = "NOERROR"
        break

    return {
        "query": query["id"],
        "profile": profile["id"],
        "rcode": rcode,
        "termination": termination,
        "final_name": current,
        "answer": answer,
        "trace": trace,
    }


def projection(run):
    return (
        run["rcode"],
        frozenset((rec["owner"], rec["type"], rec["data"]) for rec in run["answer"]),
    )


